import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Claude Design: A Guide for Frontend Engineers","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/claude/claude-design.md","filePath":"products/ai-coding/claude/claude-design.md","lastUpdated":1787048027000}'),s={name:"products/ai-coding/claude/claude-design.md"};function r(i,e,d,l,c,p){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="claude-design-a-guide-for-frontend-engineers" tabindex="-1">Claude Design: A Guide for Frontend Engineers <a class="header-anchor" href="#claude-design-a-guide-for-frontend-engineers" aria-label="Permalink to &quot;Claude Design: A Guide for Frontend Engineers&quot;">​</a></h1><p>Claude Design is a new AI design interface released by Anthropic on April 17, 2026 as a research preview product from Anthropic Labs. It&#39;s designed for the loop that frontend engineers care about: ingest a codebase, generate on-brand prototypes, iterate through conversation, then hand off the results to Claude Code for production deployment. It&#39;s powered by <strong>Claude Opus 4.7</strong> (Anthropic&#39;s most capable vision model), reads your real code repository during onboarding—colors, fonts, component naming, spacing conventions, state patterns—and treats every future project as an extension of this system, not a blank slate.</p><p>The strategic positioning to understand is: <strong>Claude Design is the exploration frontend, Claude Code is the production backend, and Canva is the downstream publishing outlet</strong>. Figma is conspicuously absent from the export targets. This manual teaches you how to leverage this loop to build websites faster, rather than getting bogged down by tools.</p><hr><h2 id="overview-what-exactly-is-claude-design" tabindex="-1">Overview: What Exactly Is Claude Design <a class="header-anchor" href="#overview-what-exactly-is-claude-design" aria-label="Permalink to &quot;Overview: What Exactly Is Claude Design&quot;">​</a></h2><p>Claude Design lets you describe a website, prototype, landing page, presentation deck, or cutting-edge interaction (shaders, 3D, voice, video), and returns a working version in seconds that respects your brand guidelines. It <strong>runs only on the web, accessible at claude.ai/design</strong>, with a dual-pane layout: conversation on the left, live canvas on the right. Under the hood, everything is code—typically HTML/CSS/JS rendered into a canvas artifact—this is why <strong>&quot;Export as standalone HTML&quot; and &quot;Handoff to Claude Code&quot; are the natural endpoints for engineers</strong>, while Canva, PDF, and PPTX serve non-engineering audiences.</p><p>Three design primitives distinguish it from v0, Lovable, Bolt, and Figma Make.</p><p>First, <strong>design systems are extracted from real codebases</strong> (GitHub repo link or local directory upload), then refined into org-level systems that every future project automatically inherits—color tokens, spacing conventions, fonts, component structure, CSS approach (Tailwind, CSS Modules, styled-components are all recognized), framework patterns.</p><p>Second, <strong>Web capture tool can scrape live elements from any URL</strong>, enabling prototypes that match actual products rather than rough approximations.</p><p>Third, <strong>fine-grained control combines four editing modes</strong>: conversational structural prompts, inline comments on specific elements, direct text editing on the canvas, <strong>and adjustment knobs—sliders dynamically generated by Claude per design</strong>, for spacing, colors, border radius, grid, opacity, fonts.</p><p>Model choice also affects output quality. Opus 4.7 has a distinct &quot;personal style&quot;—warm off-white backgrounds (~#F4F1EA), serif display fonts, italic flourishes, earthy tones—this makes editorial and portfolio work beautiful, but <strong>will backfire on dashboards, dev tools, fintech, and enterprise UI unless you explicitly counter-prompt</strong>. Budget-wise, Opus 4.7 is priced at $5/M input tokens and $25/M output tokens, and Claude Design uses its own weekly quota, independent of Claude chat and Claude Code—treat this quota as a hard constraint.</p><h3 id="what-each-plan-gets" tabindex="-1">What Each Plan Gets <a class="header-anchor" href="#what-each-plan-gets" aria-label="Permalink to &quot;What Each Plan Gets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Plan</th><th>Access</th><th>Quota Profile</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Pro</strong></td><td>Enabled by default</td><td>Quick exploration, one-off use</td><td>PCWorld reviewer burned 80% of weekly quota in 25 min with 3 variants—pace accordingly</td></tr><tr><td><strong>Max 5x</strong></td><td>Enabled by default</td><td>Semi-regular use—PMs and engineers doing regular mockups</td><td>Suitable for frontend engineers with consistent output</td></tr><tr><td><strong>Max 20x</strong></td><td>Enabled by default</td><td>Heavy use—designers and creatives</td><td>True production-grade volume</td></tr><tr><td><strong>Team</strong></td><td>Enabled by default</td><td>Per-seat weekly quota (Standard / Premium)</td><td>Supports org-wide sharing</td></tr><tr><td><strong>Enterprise (Traditional seats)</strong></td><td><strong>Disabled by default</strong>—admin must enable</td><td>Per-seat weekly quota, Standard and Premium tiers</td><td>Controlled via custom roles (RBAC)</td></tr><tr><td><strong>Enterprise (Usage-based)</strong></td><td>Disabled by default</td><td>Standard API pricing; <strong>one-time credit ~20 prompts, expires July 17, 2026</strong></td><td>Credits consumed before org account</td></tr></tbody></table><p>Quotas <strong>are per-user, not shared</strong>. Additional usage can be purchased at API rates when exceeded. No free tier. Data residency is not yet supported; audit logs and usage analytics are also not yet available—these are known gaps from the Labs period.</p><hr><h2 id="quick-start-your-first-30-minutes" tabindex="-1">Quick Start: Your First 30 Minutes <a class="header-anchor" href="#quick-start-your-first-30-minutes" aria-label="Permalink to &quot;Quick Start: Your First 30 Minutes&quot;">​</a></h2><p>Open <strong>claude.ai/design</strong>, or click the palette icon in the claude.ai left sidebar. Enterprise users who don&#39;t see it should have their admin go to <em>Organization settings → Capabilities → Anthropic Labs → Claude Design</em> and toggle it on. The homepage offers four project types—prototype (wireframe or hi-fi), slides, start from template, other—with project settings panel on the left and design archive on the right.</p><p><strong>Before anything else, set up your design system</strong>. Multiple first-hand reviewers called this the single highest-ROI action—it&#39;s the dividing line between &quot;generic AI output&quot; and &quot;looks like our product.&quot; Go to <em>Organization settings → Design system</em>, where you can link a GitHub repo, upload a local directory, or upload brand assets separately (fonts, logo, color palette).</p><p><strong>For real codebases, link a specific subdirectory, not the entire monorepo</strong>—Chrome will choke on large file trees, and Anthropic explicitly warns against including <code>.git/</code> or <code>node_modules/</code>. Expect large codebases to take 15–20 minutes to ingest; pure asset uploads complete in under 5 minutes. Once Claude has processed your color system, fonts, component inventory (buttons, cards, dialogs, navigation), spacing conventions, and framework patterns, remember to toggle the <strong>Published</strong> switch so every new project applies this system. Teams can maintain multiple systems for multi-brand scenarios—the <strong>Remix</strong> button opens a conversational editor that lets you refine tokens later.</p><p>After configuration, your first project is ready: describe what you want in the chat, watch Claude generate on the canvas, then iterate. Claude will proactively ask clarification questions—<strong>answer these seriously and specifically</strong>, as reviewers universally report this opening dialogue determines most of the final quality.</p><hr><h2 id="site-building-workflows-four-end-to-end-patterns" tabindex="-1">Site-Building Workflows: Four End-to-End Patterns <a class="header-anchor" href="#site-building-workflows-four-end-to-end-patterns" aria-label="Permalink to &quot;Site-Building Workflows: Four End-to-End Patterns&quot;">​</a></h2><h3 id="pattern-1-new-marketing-or-landing-page" tabindex="-1">Pattern 1: New Marketing or Landing Page <a class="header-anchor" href="#pattern-1-new-marketing-or-landing-page" aria-label="Permalink to &quot;Pattern 1: New Marketing or Landing Page&quot;">​</a></h3><p>For scenarios where you have brand guidelines but no specific page precedent. Start with a structured prompt on the canvas (templates below), let Claude ask its 3–5 clarification questions, accept the first version, then iterate in this order—dialogue for structure, inline comments for sections, sliders for fine-tuning, direct editing for copy.</p><p>Once layout stabilizes, prompt <code>&quot;Show me the empty state, error state, and loading state for the signup form&quot;</code> to get these variants into the export bundle. Finally, export as <strong>standalone HTML</strong> (for static hosting deployment) or <strong>handoff to Claude Code</strong> (if you want production-grade code written against existing components in your repo).</p><h3 id="pattern-2-rebuilding-or-extending-an-existing-page" tabindex="-1">Pattern 2: Rebuilding or Extending an Existing Page <a class="header-anchor" href="#pattern-2-rebuilding-or-extending-an-existing-page" aria-label="Permalink to &quot;Pattern 2: Rebuilding or Extending an Existing Page&quot;">​</a></h3><p>This is where <strong>web capture</strong> really shines. With your codebase already linked, start a new project and prompt: <code>&quot;Use web capture to scrape the hero and pricing sections from acme.com/pricing, then rebuild this page with our design system, but replace the pricing tiers with these three: [specific content]&quot;</code>.</p><p>Claude will pull the live DOM, map visual elements to your tokens, and render a version that&#39;s visually faithful but built with real components. Brilliant reports this pattern compresses complex pages from <strong>20+ prompts in other tools down to 2 prompts in Claude Design</strong>.</p><h3 id="pattern-3-dashboards-and-data-dense-saas-ui" tabindex="-1">Pattern 3: Dashboards and Data-Dense SaaS UI <a class="header-anchor" href="#pattern-3-dashboards-and-data-dense-saas-ui" aria-label="Permalink to &quot;Pattern 3: Dashboards and Data-Dense SaaS UI&quot;">​</a></h3><p>Opus 4.7&#39;s default editorial aesthetic is a liability here. <strong>You must explicitly counter-prompt</strong>: specify &quot;dense information layout, sans-serif fonts (avoid Inter/Roboto/system fonts), optional dark theme, data-first hierarchy, minimal decoration.&quot; Reference your design system by component names (<code>&quot;Use PrimaryButton, DataTable, FilterChip&quot;</code>).</p><p><strong>Ask for 2–3 layout variants upfront</strong>, rather than iterating repeatedly on a bad option—both saves tokens and converges faster. Prompt interactions like this: <code>&quot;Add filtering interactions, column sorting, row-click drilldown to open drawer&quot;</code>. Before handoff, walk Claude through empty states, error states, loading states.</p><h3 id="pattern-4-stakeholder-review-before-code" tabindex="-1">Pattern 4: Stakeholder Review Before Code <a class="header-anchor" href="#pattern-4-stakeholder-review-before-code" aria-label="Permalink to &quot;Pattern 4: Stakeholder Review Before Code&quot;">​</a></h3><p>When design needs consensus, share an <strong>org-wide link</strong> with comment or edit permissions. Edit permissions unlock <strong>group chat with Claude</strong>, so multiple colleagues can iterate together on the same canvas and in the same conversation—this isn&#39;t functionally equivalent to Figma&#39;s multi-cursor mode, and per early HN reviewers, <strong>may be a stronger collaboration model for conversational work</strong>.</p><p>Once consensus is reached, use <code>&quot;Save this version, then try a completely different direction&quot;</code> to create a snapshot branch, then hand off to the next stage.</p><h3 id="the-official-end-to-end-loop" tabindex="-1">The Official End-to-End Loop <a class="header-anchor" href="#the-official-end-to-end-loop" aria-label="Permalink to &quot;The Official End-to-End Loop&quot;">​</a></h3><p>From Anthropic&#39;s own tutorial: <strong>(1)</strong> prompt describing the feature → <strong>(2)</strong> Claude generates first version based on your org&#39;s design system and linked codebase → <strong>(3)</strong> iterate via inline comments and dialogue → <strong>(4)</strong> share internal URL for async review → <strong>(5)</strong> generate alternatives → <strong>(6)</strong> verify real components were used → <strong>(7)</strong> export → handoff to Claude Code → <strong>(8)</strong> Claude Code writes production code from the prototype, not from scratch.</p><hr><h2 id="prompt-templates-copy-and-use" tabindex="-1">Prompt Templates: Copy and Use <a class="header-anchor" href="#prompt-templates-copy-and-use" aria-label="Permalink to &quot;Prompt Templates: Copy and Use&quot;">​</a></h2><p>The official prompt structure is <strong>Goal + Layout + Content + Audience</strong>. Claude will ask follow-up questions if you miss any—answer specifically. The templates below bake this structure in.</p><h3 id="marketing-landing-pages" tabindex="-1">Marketing / Landing Pages <a class="header-anchor" href="#marketing-landing-pages" aria-label="Permalink to &quot;Marketing / Landing Pages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build a landing page for [Product Name], which is [one-sentence positioning].</span></span>
<span class="line"><span>Audience: [primary user persona, pain points, expertise level].</span></span>
<span class="line"><span>From top to bottom include: hero section (with [specific CTA]), social proof bar,</span></span>
<span class="line"><span>three-column feature grid, interactive demo, pricing (3 tiers: [tier names]), FAQ, footer.</span></span>
<span class="line"><span>Tone: [e.g., technical but approachable, not salesy].</span></span>
<span class="line"><span>Use our design system, prefer [dark|light] theme.</span></span>
<span class="line"><span>Show me 2 layout variants for the hero section.</span></span></code></pre></div><h3 id="pricing-pages" tabindex="-1">Pricing Pages <a class="header-anchor" href="#pricing-pages" aria-label="Permalink to &quot;Pricing Pages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Design a pricing page with 3 tiers ([tier names]) plus an enterprise consultation card.</span></span>
<span class="line"><span>Include monthly/annual toggle (show % savings), feature comparison table below pricing cards,</span></span>
<span class="line"><span>FAQ section. Middle tier should be visually recommended. Use our PrimaryButton</span></span>
<span class="line"><span>and PricingCard components. Audience: [technical decision makers | SMB owners].</span></span></code></pre></div><h3 id="product-pages-saas-app-ui" tabindex="-1">Product Pages / SaaS App UI <a class="header-anchor" href="#product-pages-saas-app-ui" aria-label="Permalink to &quot;Product Pages / SaaS App UI&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Design a [page name] for [product]. This is a [data-dense dashboard |</span></span>
<span class="line"><span>content-first reading interface | transactional workflow].</span></span>
<span class="line"><span>Key elements: [list].</span></span>
<span class="line"><span>Interactions: [list, e.g., filtering, sorting, drill-down].</span></span>
<span class="line"><span>Reference our design system by component name where possible.</span></span>
<span class="line"><span>Counter the default aesthetic—I want sans-serif fonts, dense information hierarchy,</span></span>
<span class="line"><span>neutral grays with a single accent color, no cream backgrounds or serif fonts.</span></span>
<span class="line"><span>Include empty state, loading state, error state.</span></span></code></pre></div><h3 id="cloning-rebuilding-existing-pages" tabindex="-1">Cloning / Rebuilding Existing Pages <a class="header-anchor" href="#cloning-rebuilding-existing-pages" aria-label="Permalink to &quot;Cloning / Rebuilding Existing Pages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use the web capture tool to scrape the [section name] from [URL].</span></span>
<span class="line"><span>Rebuild it using our design system. Preserve [what to preserve:</span></span>
<span class="line"><span>information hierarchy, interaction model], but replace [what to change].</span></span>
<span class="line"><span>Show me the result, side-by-side with the captured original.</span></span></code></pre></div><h3 id="investor-demo-sites" tabindex="-1">Investor / Demo Sites <a class="header-anchor" href="#investor-demo-sites" aria-label="Permalink to &quot;Investor / Demo Sites&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>An investor demo site with [N] pages, for [stage] [category], in [industry] industry.</span></span>
<span class="line"><span>Audience: [investor type]. One-pager takeaway conclusion: [specific numbers-backed results].</span></span>
<span class="line"><span>Sections: problem, solution, demo, business progress, team, ask.</span></span>
<span class="line"><span>Tone: [confident / restrained]. Use our brand.</span></span></code></pre></div><h3 id="frontend-aesthetics-config-block-from-the-anthropic-cookbook" tabindex="-1">Frontend Aesthetics Config Block (from the Anthropic Cookbook) <a class="header-anchor" href="#frontend-aesthetics-config-block-from-the-anthropic-cookbook" aria-label="Permalink to &quot;Frontend Aesthetics Config Block (from the Anthropic Cookbook)&quot;">​</a></h3><p>When Opus 4.7&#39;s default &quot;AI look&quot; creeps in (centered purple gradient on white, Inter/Roboto, Space Grotesk), paste this in as a system-level prefix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;frontend_aesthetics&gt;</span></span>
<span class="line"><span>Fonts: Avoid Inter, Roboto, Arial, system fonts.</span></span>
<span class="line"><span>Prefer recognizable options: JetBrains Mono, Playfair Display,</span></span>
<span class="line"><span>Clash Display, Bricolage Grotesque, IBM Plex, Fraunces,</span></span>
<span class="line"><span>chosen according to content.</span></span>
<span class="line"><span>Colors: Dominant neutral with sharp accent. Use CSS variables.</span></span>
<span class="line"><span>Inspired by IDE themes or cultural aesthetics, no generic gradients.</span></span>
<span class="line"><span>Motion: Pure CSS for HTML, Motion library for React. Focus on</span></span>
<span class="line"><span>one carefully orchestrated page load moment with staggered reveal.</span></span>
<span class="line"><span>Backgrounds: Layered gradients or geometric patterns, no solid fills.</span></span>
<span class="line"><span>Avoid: Purple gradients on white, centered hero, generic cards.</span></span>
<span class="line"><span>&lt;/frontend_aesthetics&gt;</span></span></code></pre></div><h3 id="iterative-prompting-patterns" tabindex="-1">Iterative Prompting Patterns <a class="header-anchor" href="#iterative-prompting-patterns" aria-label="Permalink to &quot;Iterative Prompting Patterns&quot;">​</a></h3><ul><li><strong>Structural changes via dialogue</strong>: <code>&quot;Move the pricing table above the feature grid, add a testimonial carousel between hero and features&quot;</code></li><li><strong>Component-level edits via inline comment</strong>: <code>&quot;Increase the padding on this button&quot;</code>, <code>&quot;Change this to a dropdown menu&quot;</code>, <code>&quot;Use the primary brand color here&quot;</code></li><li><strong>Micro-adjustments via sliders</strong>: <code>&quot;Give me sliders to control hero spacing, border radius, accent color opacity&quot;</code></li><li><strong>Copy edits by clicking directly on the element</strong></li><li><strong>Branch while preserving the original</strong>: <code>&quot;Save this version, then try a completely different direction—more minimal, more editorial&quot;</code></li></ul><hr><h2 id="claude-code-integration-handoff-bundle" tabindex="-1">Claude Code Integration: Handoff Bundle <a class="header-anchor" href="#claude-code-integration-handoff-bundle" aria-label="Permalink to &quot;Claude Code Integration: Handoff Bundle&quot;">​</a></h2><p>The handoff bundle is the engineer&#39;s killer feature, and what Brilliant&#39;s team calls &quot;the seamless leap from prototype to production.&quot; From any project&#39;s export menu (top-right), choose <strong>Handoff to Claude Code → Send to local coding agent</strong> or <strong>Send to Claude Code Web</strong>.</p><h3 id="what-s-actually-in-the-bundle" tabindex="-1">What&#39;s Actually in the Bundle <a class="header-anchor" href="#what-s-actually-in-the-bundle" aria-label="Permalink to &quot;What&#39;s Actually in the Bundle&quot;">​</a></h3><ul><li>Project design files</li><li><strong>Full conversation transcript</strong> (every design decision and reasoning process transfers with it)</li><li>A <strong>README</strong> instructing the receiving model how to understand the design</li><li>A <strong>pre-built prompt containing the bundle URL</strong>, which you paste into Claude Code</li></ul><p>This isn&#39;t an API push—it&#39;s a URL-based file delivery pattern. Claude Code downloads the bundle, reads the README, and operates on it as a project workspace. The bundle&#39;s JSON schema is currently unpublished.</p><h3 id="why-the-conversation-matters-more-than-the-mockup" tabindex="-1">Why the Conversation Matters More Than the Mockup <a class="header-anchor" href="#why-the-conversation-matters-more-than-the-mockup" aria-label="Permalink to &quot;Why the Conversation Matters More Than the Mockup&quot;">​</a></h3><p>The tutorial makes it clear: <em>&quot;If you mentioned components by specific name in the design conversation, those names carry into handoff&quot;</em>, and <em>&quot;When you make design decisions during iteration (&#39;we chose tabs over sidebar because users need to see all sections at once&#39;), that reasoning becomes context for the implementation phase&quot;</em>.</p><p>In practice this means: <strong>how you speak during design determines the quality of downstream code</strong>—naming components, stating rationales, probing edge cases.</p><h3 id="framework-choice-is-neutral-your-repo-decides" tabindex="-1">Framework Choice Is Neutral: Your Repo Decides <a class="header-anchor" href="#framework-choice-is-neutral-your-repo-decides" aria-label="Permalink to &quot;Framework Choice Is Neutral: Your Repo Decides&quot;">​</a></h3><p>Because Claude Design and Claude Code can point to the same codebase, Claude Code writes using your repo&#39;s existing framework and styling approach—React, Vue, Tailwind, CSS Modules, styled-components are all confirmed usable by third-party reviewers. Anthropic doesn&#39;t lock output to a specific framework; your repo decides everything.</p><h3 id="pre-export-checklist" tabindex="-1">Pre-Export Checklist <a class="header-anchor" href="#pre-export-checklist" aria-label="Permalink to &quot;Pre-Export Checklist&quot;">​</a></h3><p>Before hitting enter, run through this list:</p><ol><li>Did you reference components by name in the conversation?</li><li>Did you record design rationale (&quot;we chose tabs because…&quot;)?</li><li>Did you generate empty states, error states, loading states?</li><li>Did you verify responsive behavior on mobile/tablet/desktop?</li><li>Did you run an accessibility audit? — <code>&quot;Review this design for contrast, hierarchy, keyboard navigation&quot;</code>, fix all discovered issues</li></ol><p>Each item goes into the bundle, reducing back-and-forth in Claude Code.</p><hr><h2 id="export-and-canva-choose-the-right-target" tabindex="-1">Export and Canva: Choose the Right Target <a class="header-anchor" href="#export-and-canva-choose-the-right-target" aria-label="Permalink to &quot;Export and Canva: Choose the Right Target&quot;">​</a></h2><p>The export menu in the top-right gives you seven paths. Choose by audience.</p><table tabindex="0"><thead><tr><th>Target</th><th>What you actually get</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Standalone HTML</strong></td><td>Self-contained HTML, CSS embedded; interactions (voice, video, shaders, 3D, AI) preserved as code</td><td>Static hosting deployment, demos, quick sharing with engineering</td></tr><tr><td><strong>Handoff to Claude Code</strong></td><td>Design files + conversation + README + prompt URL</td><td>Production-grade implementation against real repo</td></tr><tr><td><strong>Send to Canva</strong></td><td><strong>Fully editable</strong> Canva design, not a flat image—enters Canva Visual Suite via Design Engine</td><td>Marketing polish, brand team handoff, social/publishing</td></tr><tr><td><strong>Download as .zip</strong></td><td>Complete project folder</td><td>Archival, offline handoff</td></tr><tr><td><strong>Export as PDF</strong></td><td>Static render</td><td>Stakeholder review, email attachments</td></tr><tr><td><strong>Export as PPTX</strong></td><td>PowerPoint/Google Slides file</td><td>Executive presentations, client demos</td></tr><tr><td><strong>Org internal URL</strong></td><td>View-only, comment, or edit permissions</td><td>Async team review; edit permissions unlock group chat with Claude</td></tr></tbody></table><h3 id="canva-is-a-deep-integration-not-a-simple-export" tabindex="-1">Canva Is a Deep Integration, Not a Simple Export <a class="header-anchor" href="#canva-is-a-deep-integration-not-a-simple-export" aria-label="Permalink to &quot;Canva Is a Deep Integration, Not a Simple Export&quot;">​</a></h3><p>This partnership began in July 2025 when Canva released <strong>Canva MCP for Claude</strong>; brand-aware generation joined in January 2026; and native Claude Design export launched on April 17.</p><p>Under the hood, it uses Canva&#39;s <strong>Design Engine, Visual Suite, and the new HTML import capability from Canva AI 2.0</strong>. Designs land as structured, editable objects, respect Canva Brand Kits, can be embedded in Canva Presentations, connected to Canva Forms/Sheets, or published with a custom domain as Canva Website.</p><p>The reverse flow (Canva → Claude Design) isn&#39;t native import, but Canva MCP already allows Claude to read Canva content in everyday conversations.</p><h3 id="figma-s-absence-is-intentional" tabindex="-1">Figma&#39;s Absence Is Intentional <a class="header-anchor" href="#figma-s-absence-is-intentional" aria-label="Permalink to &quot;Figma&#39;s Absence Is Intentional&quot;">​</a></h3><p>Anthropic CPO Mike Krieger resigned from Figma&#39;s board three days before launch; Figma stock dropped ~5–7% on launch day. If you need Figma, reviewers recommend the existing <strong>Figma MCP server + Claude Code</strong> path—this is separate from Claude Design.</p><hr><h2 id="best-practices-techniques-that-compound" tabindex="-1">Best Practices: Techniques That Compound <a class="header-anchor" href="#best-practices-techniques-that-compound" aria-label="Permalink to &quot;Best Practices: Techniques That Compound&quot;">​</a></h2><p><strong>Design system configuration is the single highest-ROI action</strong>. Without it, generic; with it, every project inherits your brand. Do it day one, use a real GitHub repo not uploaded assets, link a subdirectory not a monorepo.</p><p><strong>Match editing mode to change size</strong>. Dialogue for structural changes (layout, sections, themes), inline comments for component-level edits, sliders for real-time fine-tuning, direct text editing for copy. <strong>Don&#39;t regenerate when you can fine-tune</strong>—regeneration burns quota and loses context.</p><p><strong>Be specific down to numbers</strong>. <code>&quot;Compress form field spacing to 8px&quot;</code> beats <code>&quot;this looks wrong&quot;</code>. <code>&quot;Replace the current near-black with #0F172A&quot;</code> beats <code>&quot;make it darker&quot;</code>. Pixels and hex values shortcut clarification loops.</p><p><strong>Ask for 2–3 options upfront</strong>. Side-by-side comparison beats repeated iteration on a single bad option—both faster convergence and fewer tokens.</p><p><strong>For non-editorial work, counter-prompt Opus 4.7&#39;s default style</strong>. The model defaults to cream/serifs/earth tones—beautiful for portfolios, but wrong for dashboards, dev tools, finance, healthcare, enterprise admin backends. Explicitly prompt for sans-serif, data density, dark or neutral themes.</p><p><strong>Manage your quota</strong>. Downgrade cleanup tasks (copy editing, minor rearrangements) <strong>to Sonnet 4.6</strong>, reserve generation and structural moves for Opus 4.7. PCWorld&#39;s reviewer burned 80% of Pro weekly quota in 25 minutes—this ceiling is real.</p><p><strong>Record rationale during iteration</strong>, because the conversation itself is the handoff to Claude Code. &quot;We chose tabs over sidebar because users need to see all sections at once&quot;—this sentence becomes implementation context downstream.</p><p><strong>Check completeness before handoff</strong>. Have Claude show empty states, error states, loading states; request one accessibility audit (contrast, hierarchy, keyboard navigation); verify mobile/tablet/desktop. Each issue found and fixed here is one round-trip saved in Claude Code.</p><h3 id="the-three-most-common-mistakes" tabindex="-1">The Three Most Common Mistakes <a class="header-anchor" href="#the-three-most-common-mistakes" aria-label="Permalink to &quot;The Three Most Common Mistakes&quot;">​</a></h3><ul><li><strong>Skipping design system configuration</strong>: prototypes become generic, don&#39;t look like your product</li><li><strong>Vague feedback (&quot;make it look better&quot;)</strong>: burns tokens and iterations—give specific numbers</li><li><strong>Confusing Undo and Back</strong>: <strong>you can irreversibly wipe the entire session</strong>—PCWorld&#39;s reviewer lost a full work session this way</li></ul><h3 id="known-bugs-and-workarounds" tabindex="-1">Known Bugs and Workarounds <a class="header-anchor" href="#known-bugs-and-workarounds" aria-label="Permalink to &quot;Known Bugs and Workarounds&quot;">​</a></h3><ul><li>Inline comments occasionally disappear before Claude reads them—paste comment text into dialogue</li><li>Save errors in compact view—switch to full view</li><li>Upstream errors in conversation—open new conversation tab within same project</li><li>Large monorepos choke the browser—link specific subdirectory</li></ul><hr><h2 id="closing-the-loop-is-the-product" tabindex="-1">Closing: The Loop Is the Product <a class="header-anchor" href="#closing-the-loop-is-the-product" aria-label="Permalink to &quot;Closing: The Loop Is the Product&quot;">​</a></h2><p>Claude Design&#39;s bet is this: the correct atomic unit of modern product work is neither the Figma frame nor the React component—<strong>it&#39;s a conversation that can produce artifacts in both directions</strong>. For frontend engineers building websites, this means the tool only compounds when you treat it as Claude Code&#39;s front door, not the destination.</p><p>Ingest your repo once, speak in component names, record rationale during iteration, then let the handoff bundle transport the full design conversation into production. The strongest teams—Brilliant from 20+ prompts down to 2, Datadog compressing a week of reviews into one conversation—don&#39;t use Claude Design as a prettier v0; they treat it as a <strong>shared context prototyping layer that feeds their existing codebase and existing Claude Code workflows</strong>.</p><p>The limitations of the research preview period are real (weekly quotas bite, no audit logs, no data residency, no API, multi-person collaboration is rough), but for engineers already living in Claude Code, this integrated loop is the highest-leverage design tool Anthropic has released to date.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/news/claude-design-anthropic-labs" target="_blank" rel="noreferrer">Introducing Claude Design by Anthropic Labs</a> — Official announcement</li><li><a href="https://claude.ai/design" target="_blank" rel="noreferrer">Claude Design product page</a></li><li><a href="https://support.claude.com/en/articles/14604416-get-started-with-claude-design" target="_blank" rel="noreferrer">Get started with Claude Design</a> — Official quick start</li><li><a href="https://support.claude.com/en/" target="_blank" rel="noreferrer">Claude Design subscription and pricing</a> — original article URL has been retired; link to the support root for the current entry point</li><li><a href="https://support.claude.com/en/articles/14604406-claude-design-admin-guide-for-team-and-enterprise-plans" target="_blank" rel="noreferrer">Team and Enterprise admin guide</a></li><li><a href="https://support.claude.com/en/articles/14604397-set-up-your-design-system-in-claude-design" target="_blank" rel="noreferrer">Design system setup guide</a></li><li><a href="https://claude.com/resources/tutorials/using-claude-design-for-prototypes-and-ux" target="_blank" rel="noreferrer">Claude Design prototypes and UX tutorial</a></li></ul>`,101)])])}const b=t(s,[["render",r]]);export{f as __pageData,b as default};
